"""Embed the preserved upstream RGB sample for the Release C preprocessing gate."""
from pathlib import Path

def main():
    root=Path(__file__).resolve().parent
    data=(root/'sample_image.rgb').read_bytes()
    assert len(data)==192*192*3
    lines=['// Copyright 2022 Arm Limited and/or its affiliates <open-source-office@arm.com>',
           '// Generated by generate_demo_tests.py; source attribution: NOTICE.md.',
           '// SPDX-License-Identifier: Apache-2.0','#pragma once','#include <stdint.h>',
           'static const uint8_t detection_sample_rgb[110592] = {']
    lines.extend('    '+','.join(str(x) for x in data[i:i+32])+',' for i in range(0,len(data),32))
    (root/'demo_test_data.h').write_text('\n'.join(lines+['};','']))

if __name__=='__main__': main()
